    static func resolve(_ rawValue: String?) -> AircraftTypeResolution? {
        guard let rawValue else { return nil }
        let trimmed = rawValue.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return nil }
        let normalized = trimmed
            .uppercased()
            .filter { $0.isLetter || $0.isNumber }

        if let entry = exact[normalized] {
            return .init(
                code: entry.code,
                label: entry.label,
                iconSlug: entry.slug,
                exactCode: true
            )
        }
        if let entry = aliases.first(where: {
            normalized.contains($0.needle)
        })?.entry {
            return .init(
                code: nil,
                label: entry.label,
                iconSlug: entry.slug,
                exactCode: false
            )
        }

        // Unknown 2–4 character values are still valid candidate ICAO
        // designators. Preserve them instead of inventing a known model.
        if (2...4).contains(normalized.count) {
            return .init(
                code: normalized,
                label: normalized,
                iconSlug: nil,
                exactCode: true
            )
        }
        return .init(
            code: nil,
            label: trimmed,
            iconSlug: nil,
            exactCode: false
        )
    }
